actions.script:
                if (!ec.user.isInGroup("ADMIN")) { ec.message.addError("Access denied."); return }
                def s = ec.entity.find("zenith.erp.saas.SaasSubscription").condition("subscriptionId", subscriptionId).one()
                if (s == null) { ec.message.addError("Subscription not found."); return }
                if (ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('tenantId',s.tenantId)
                        .condition('configKey','MANUAL_PLAN_SUBSCRIPTION').one()?.configValue) {
                    ec.message.addError('Use Tenant Plans to manage this manual assignment.'); return
                }
                def cur = s.statusId
                def tenant = ec.entity.find("zenith.erp.saas.SaasTenant").condition("tenantId", s.tenantId).one()
                boolean flagship = (tenant?.organizationPartyId == '100000')
                def audit = { ev, desc -> ec.service.sync().name("create#zenith.erp.saas.SaasAuditLog")
                    .parameters([tenantId:s.tenantId, eventType:ev, eventDate:ec.user.nowTimestamp, userId:ec.user.userId, description:desc]).call() }
                def setStatus = { to -> ec.service.sync().name("update#zenith.erp.saas.SaasSubscription")
                    .parameters([subscriptionId:subscriptionId, statusId:to]).call() }

                switch (action) {
                    case 'activate':
                        if (cur != 'SubTrial') { ec.message.addError("Only a Trial subscription can be activated."); return }
                        setStatus('SubActive'); audit('SUB_ACTIVATE','Activated (Trial -> Active)'); ec.message.addMessage("Subscription activated."); break
                    case 'pause':
                        if (cur != 'SubActive') { ec.message.addError("Only an Active subscription can be paused."); return }
                        if (flagship) { ec.message.addError("The flagship live tenant (MARUTHI) is protected from pause."); return }
                        setStatus('SubPaused'); audit('SUB_PAUSE','Paused'); ec.message.addMessage("Subscription paused."); break
                    case 'resume':
                        if (cur != 'SubPaused') { ec.message.addError("Only a Paused subscription can be resumed."); return }
                        setStatus('SubActive'); audit('SUB_RESUME','Resumed (Paused -> Active)'); ec.message.addMessage("Subscription resumed."); break
                    case 'reactivate':
                        if (cur != 'SubPastDue') { ec.message.addError("Only a Past-Due subscription can be reactivated."); return }
                        setStatus('SubActive'); audit('SUB_REACTIVATE','Reactivated (Past Due -> Active)'); ec.message.addMessage("Subscription reactivated."); break
                    case 'cancel':
                        if (!(cur in ['SubTrial','SubActive','SubPaused','SubPastDue'])) { ec.message.addError("This subscription can't be cancelled from its current status."); return }
                        if (flagship) { ec.message.addError("The flagship live tenant (MARUTHI) is protected from cancellation."); return }
                        ec.service.sync().name("update#zenith.erp.saas.SaasSubscription")
                            .parameters([subscriptionId:subscriptionId, statusId:'SubCancelled', cancelledDate:ec.user.nowTimestamp, cancelReason:'Cancelled by admin']).call()
                        audit('SUB_CANCEL','Cancelled by admin'); ec.message.addMessage("Subscription cancelled."); break
                    case 'renew':
                    case 'generate':
                        if (!(cur in ['SubTrial','SubActive','SubPastDue'])) { ec.message.addError("Can only invoice an Active / Trial / Past-Due subscription."); return }
                        def plan = ec.entity.find("zenith.erp.saas.SaasPlan").condition("planId", s.planId).one()
                        def amount = ((s.billingCycle == 'Yearly' ? plan?.yearlyPrice : plan?.monthlyPrice) ?: s.amount ?: 0) as java.math.BigDecimal
                        if (amount.signum() <= 0) { ec.message.addError("The plan price is 0 — nothing to invoice."); return }
                        def taxOut = ec.service.sync().name("zenith.subscriptions.SubscriptionServices.calculate#SubscriptionTax")
                            .parameters([organizationPartyId:'ZETAERP', customerPartyId:tenant.organizationPartyId, taxableAmount:amount, gstRate:18]).disableAuthz().call()
                        def _pf = s.renewalDate ?: java.sql.Date.valueOf(java.time.LocalDate.now())
                        def _pfLd = new java.sql.Date(_pf.getTime()).toLocalDate()
                        def _pt = java.sql.Date.valueOf(s.billingCycle == 'Yearly' ? _pfLd.plusYears(1) : _pfLd.plusMonths(1))
                        def _prefix = 'SAAS-' + java.time.LocalDate.now().toString().substring(0,7).replace('-','') + '-'
                        def _last = ec.entity.find("zenith.erp.saas.SaasInvoice").condition("invoiceNumber","like",_prefix+'%').orderBy("-invoiceNumber").disableAuthz().list()
                        int _seq = 1
                        if (_last) { try { _seq = (_last[0].invoiceNumber.toString().substring(_prefix.length()) as Integer) + 1 } catch (e) { _seq = _last.size() + 1 } }
                        def _invNo = _prefix + String.format('%04d', _seq)
                        ec.service.sync().name("create#zenith.erp.saas.SaasInvoice").parameters([
                            tenantId:s.tenantId, subscriptionId:subscriptionId, invoiceNumber:_invNo, invoiceDate:ec.user.nowTimestamp,
                            dueDate:java.sql.Date.valueOf(java.time.LocalDate.now().plusDays(7)), periodFrom:_pf, periodTo:_pt,
                            subtotal:amount, taxAmount:(taxOut?.taxAmount ?: 0), cgstAmount:taxOut?.cgstAmount, sgstAmount:taxOut?.sgstAmount,
                            igstAmount:taxOut?.igstAmount, placeOfSupply:taxOut?.placeOfSupply, totalAmount:(taxOut?.totalAmount ?: amount),
                            currencyUomId:(s.currencyUomId ?: 'INR'), statusId:'SiSent']).disableAuthz().call()
                        if (action == 'renew') {
                            ec.service.sync().name("update#zenith.erp.saas.SaasSubscription").parameters([subscriptionId:subscriptionId, renewalDate:_pt]).call()
                        }
                        audit(action == 'renew' ? 'SUB_RENEW' : 'SUB_INVOICE', 'Invoice ' + _invNo + ' generated' + (action == 'renew' ? '; renewal advanced to ' + _pt : ''))
                        ec.message.addMessage("Invoice ${_invNo} generated (${amount} + GST)" + (action == 'renew' ? "; renewal date advanced to ${_pt}." : "."))
                        break
                    default: ec.message.addError("Unknown action."); return
                }
